import React, { useState, useEffect } from 'react';
import { leadsAPI } from '../services/api';

const LeadList = () => {
  const [leads, setLeads] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchLeads();
  }, []);

  const fetchLeads = async () => {
    try {
      const response = await leadsAPI.getLeads();
      setLeads(response.data);
    } catch (error) {
      console.error('Lỗi lấy leads:', error);
    } finally {
      setLoading(false);
    }
  };

  const updateStatus = async (id, status) => {
    try {
      await leadsAPI.updateLead(id, { status });
      fetchLeads();  // Refresh list
    } catch (error) {
      console.error('Lỗi cập nhật:', error);
    }
  };

  const deleteLead = async (id) => {
    if (window.confirm('Xóa lead này?')) {
      try {
        await leadsAPI.deleteLead(id);
        fetchLeads();
      } catch (error) {
        console.error('Lỗi xóa:', error);
      }
    }
  };

  if (loading) return <p>Đang tải...</p>;

  return (
    <div className="lead-list">
      <h2>Danh Sách Leads</h2>
      <table>
        <thead>
          <tr>
            <th>Tên</th>
            <th>Email</th>
            <th>Phone</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {leads.map(lead => (
            <tr key={lead._id}>
              <td>{lead.name}</td>
              <td>{lead.email}</td>
              <td>{lead.phone}</td>
              <td>
                <select value={lead.status} onChange={(e) => updateStatus(lead._id, e.target.value)}>
                  <option value="new">Mới</option>
                  <option value="processing">Xử lý</option>
                  <option value="converted">Chuyển đổi</option>
                  <option value="lost">Mất</option>
                </select>
              </td>
              <td>
                <button onClick={() => deleteLead(lead._id)}>Xóa</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default LeadList;
